/* ---------- logo ---------- */
// gills mark on a 96×64 grid: ring (focus) + accent dot + 3 gill strokes each side
function gills({ink='var(--primary)', dot='var(--accent)', sw=6, simple=false}={}){
  const g = simple ? ['M24 22L10 14','M24 42L10 50','M72 22L86 14','M72 42L86 50'] : ['M25 20L9 9','M23 32L5 32','M25 44L9 55','M71 20L87 9','M73 32L91 32','M71 44L87 55'];
  return `<circle cx="48" cy="32" r="${simple?17:18}" fill="none" stroke="${ink}" stroke-width="${simple?sw+2:sw}"/><circle cx="48" cy="32" r="${simple?6:5.5}" fill="${dot}"/>` +
    g.map(d=>`<path d="${d}" stroke="${ink}" stroke-width="${simple?sw+2:sw-1}" stroke-linecap="round"/>`).join('');
}
const markSvg = (w, o={}) => `<svg width="${w}" height="${w*64/96}" viewBox="0 0 96 64" role="img" aria-label="Axo">${gills(o)}</svg>`;
// L1: gills mark inside the app tile
function tileGills(s, theme='l'){
  const simple = s <= 32;
  const bg = theme==='d' ? '#A9D6B9' : '#1F3D2E', ink = theme==='d' ? '#10241A' : '#FFFDF8', dot = theme==='d' ? '#B8451C' : '#F0895C';
  return `<svg width="${s}" height="${s}" viewBox="0 0 100 100" role="img" aria-label="Axo app icon"><rect width="100" height="100" rx="24" fill="${bg}"/><g transform="translate(${simple?2:6} ${simple?18:20}) scale(${simple?1:.917})">${gills({ink, dot, sw:simple?7:6, simple})}</g></svg>`;
}
// L2: lowercase a wearing gills on the tile edges
function tileA(s, theme='l'){
  const bg = theme==='d' ? '#A9D6B9' : '#1F3D2E', ink = theme==='d' ? '#10241A' : '#FFFDF8', dot = theme==='d' ? '#B8451C' : '#F0895C';
  const g = ['M22 30L9 21','M20 44L5 44','M22 58L9 67','M78 30L91 21','M80 44L95 44','M78 58L91 67'];
  return `<svg width="${s}" height="${s}" viewBox="0 0 100 100" role="img" aria-label="Axo monogram"><rect width="100" height="100" rx="24" fill="${bg}"/>${g.map(d=>`<path d="${d}" stroke="${ink}" stroke-width="5" stroke-linecap="round"/>`).join('')}<text x="50" y="66" text-anchor="middle" font-family="Literata, Georgia, serif" font-weight="600" font-size="62" fill="${ink}">a</text><circle cx="67" cy="27" r="6" fill="${dot}"/></svg>`;
}
// L3: wordmark "ax" + gills mark as the o
function wordmark(h, theme='l'){
  const ink = theme==='d' ? '#EEE9DF' : '#1F3D2E', dot = theme==='d' ? '#F0895C' : '#B8451C';
  return `<span style="display:inline-flex;align-items:center;gap:${h*.02}px;color:${ink};font:600 ${h}px/1 var(--f-display);letter-spacing:-.02em">ax<svg width="${h*0.95}" height="${h*0.95*64/96}" viewBox="0 0 96 64" style="margin-top:${h*0.12}px" aria-hidden="true">${gills({ink, dot, sw:6})}</svg></span>`;
}
function renderLogo(el){
  const card = (title, note, l, d) => `<div class="logo-card"><div class="logo-stage l">${l}</div><div class="logo-stage d">${d}</div><div class="strong" style="font-size:16px">${title}</div><div class="muted" style="line-height:21px">${note}</div></div>`;
  el.innerHTML = `<div style="padding:40px 40px 0;display:flex;justify-content:space-between;align-items:end;gap:24px">
      <div><div class="label muted">LOGO · ВАРІАНТИ ПОЄДНАННЯ C + B</div><div class="serif" style="font-size:40px;line-height:48px;margin-top:6px">Зябра на плитці</div></div>
      <div class="muted" style="max-width:520px;text-align:right;line-height:21px">Кільце — фокус, помаранчева точка — момент роботи, три риски з боків — зябра аксолотля. На 32 px і менше знак спрощується до двох рисок з боку.</div></div>
    <div class="logo-sheet">
      ${card('L1 · Плитка із зябрами', 'Іконка PWA, фавікон, аватар у соцмережах. Найчистіше читається на малих розмірах. <b>Обрано як іконку.</b>',
        `${tileGills(112)}${tileGills(56)}${tileGills(32)}${tileGills(16)}`, `${tileGills(112,'d')}${tileGills(56,'d')}${tileGills(32,'d')}${tileGills(16,'d')}`)}
      ${card('L2 · «a» із зябрами', 'Монограма з концепту B, якій «виросли» зябра по краях плитки. Більш грайлива, але на 16 px літера і риски злипаються.',
        `${tileA(112)}${tileA(56)}${tileA(32)}`, `${tileA(112,'d')}${tileA(56,'d')}${tileA(32,'d')}`)}
      ${card('L3 · Wordmark «ax» + знак', 'Знак стає літерою «o». Для шапки застосунку, лендінгу, листів. <b>Обрано як логотип</b> — він ділить знак з L1.',
        `${wordmark(64)}`, `${wordmark(64,'d')}`)}
    </div>
    <div style="padding:0 40px 20px"><div class="logo-card"><div style="display:flex;justify-content:space-between;align-items:baseline;gap:16px"><div class="label muted">axl. · SVG З ОРИГІНАЛУ UI KIT · 4 ЕМОЦІЇ</div><div class="muted s">Векторизовано з артворку MYSLENNYA; колір = currentColor, обличчя — отвори в контурі, тож працює на будь-якому фоні.</div></div>
      <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:16px">${['neutral','joy','sad','playful'].map((e,i)=>`<div style="display:flex;flex-direction:column;gap:8px;align-items:center"><div class="logo-stage l" style="width:100%;min-height:0;padding:16px">${axl(e,150)}</div><div class="logo-stage d" style="width:100%;min-height:0;padding:16px"><div style="width:150px;color:#A9D6B9">${axlSvg(e)}</div></div><span class="s strong">${['нейтральний — порожні стани','радість — «готово»','сум — помилка, офлайн','грайливий — фінальний CTA'][i]}</span></div>`).join('')}</div></div></div>
    <div style="padding:0 40px 40px;display:grid;grid-template-columns:1.2fr 1fr;gap:20px">
      <div class="logo-card"><div class="label muted">LOCKUP · ІКОНКА + НАЗВА</div>
        <div class="logo-stage l" style="justify-content:flex-start;gap:40px">
          <span style="display:inline-flex;align-items:center;gap:12px">${tileGills(44)}<span class="serif" style="font-size:30px;color:#1F3D2E">axo</span></span>
          <span style="display:inline-flex;align-items:center;gap:10px">${tileGills(28)}<span class="serif" style="font-size:20px;color:#1F3D2E">axo</span></span>
          ${wordmark(32)}
        </div></div>
      <div class="logo-card"><div class="label muted">ПРАВИЛА</div>
        <ul style="margin:0;padding-left:18px;line-height:24px">
          <li>Назва завжди з малої: «axo». У тексті — «Axo».</li>
          <li>Поле навколо знака — не менше висоти кільця.</li>
          <li>Помаранчева точка лишається помаранчевою на будь-якому фоні.</li>
          <li>Мінімум: плитка 16 px, wordmark 20 px заввишки.</li>
          <li>axl. ніколи не замінює знак — це маскот, не логотип.</li>
        </ul></div>
    </div>`;
}

/* ---------- shared data ---------- */
const T = { epic:['var(--type-epic)','star'], story:['var(--type-story)','rect'], task:['var(--type-task)','ring'], bug:['var(--type-bug)','dot'] };
// Type icons as in the app (lucide, ISC): crown = epic, book-open = story, square-check = task, bug = bug, in the type colour.
const TYPE_ICON = {"epic": "<path d=\"M11.562 3.266a.5.5 0 0 1 .876 0L15.39 8.87a1 1 0 0 0 1.516.294L21.183 5.5a.5.5 0 0 1 .798.519l-2.834 10.246a1 1 0 0 1-.956.734H5.81a1 1 0 0 1-.957-.734L2.02 6.02a.5.5 0 0 1 .798-.519l4.276 3.664a1 1 0 0 0 1.516-.294z\"/><path d=\"M5 21h14\"/>", "story": "<path d=\"M12 7v14\"/><path d=\"M3 18a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h5a4 4 0 0 1 4 4 4 4 0 0 1 4-4h5a1 1 0 0 1 1 1v13a1 1 0 0 1-1 1h-6a3 3 0 0 0-3 3 3 3 0 0 0-3-3z\"/>", "task": "<rect width=\"18\" height=\"18\" x=\"3\" y=\"3\" rx=\"2\"/><path d=\"m9 12 2 2 4-4\"/>", "bug": "<path d=\"M12 20v-9\"/><path d=\"M14 7a4 4 0 0 1 4 4v3a6 6 0 0 1-12 0v-3a4 4 0 0 1 4-4z\"/><path d=\"M14.12 3.88 16 2\"/><path d=\"M21 21a4 4 0 0 0-3.81-4\"/><path d=\"M21 5a4 4 0 0 1-3.55 3.97\"/><path d=\"M22 13h-4\"/><path d=\"M3 21a4 4 0 0 1 3.81-4\"/><path d=\"M3 5a4 4 0 0 0 3.55 3.97\"/><path d=\"M6 13H2\"/><path d=\"m8 2 1.88 1.88\"/><path d=\"M9 7.13V6a3 3 0 1 1 6 0v1.13\"/>"};
const glyph = t => `<svg class="glyph" viewBox="0 0 24 24" fill="none" stroke="${T[t][0]}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:14px;height:14px">${TYPE_ICON[t]}</svg>`;
const AV = { me:['me','М'], claude:['claude','C'], ag:['ag','AG'] };
const av = w => `<span class="av ${AV[w][0]}" title="${w}">${AV[w][1]}</span>`;
const STATUS = { backlog:['Беклог','','hollow'], todo:['До роботи','var(--status-todo)'], progress:['В роботі','var(--status-progress)'], review:['На рев’ю','var(--status-review)'], done:['Готово','var(--success)'] };
const pill = s => `<span class="pill"><span class="dot ${STATUS[s][2]||''}" style="--c:${STATUS[s][1]}"></span>${STATUS[s][0]}</span>`;
const ITEMS = {
  backlog:[{r:'AXO-21',t:'story',ti:'Перейменування в застосунку та i18n',a:'me',tags:['brand']},{r:'AXO-22',t:'task',ti:'Ассети логотипа: іконки PWA, фавікон',a:'me'},{r:'AXO-25',t:'bug',ti:'Фокус-кільце не видно на кнопках',a:'claude',sev:'Високий'}],
  todo:[{r:'AXO-18',t:'story',ti:'Лендінг з реальними екранами',a:'me',tags:['landing']},{r:'AXO-19',t:'task',ti:'Темна тема: data-theme і PiP-вікно',a:'claude',blocked:'AXO-17'}],
  progress:[{r:'AXO-17',t:'task',ti:'Токени кольору в index.css',a:'claude',comments:3,act:'Claude прокоментував · 2 хв тому',focus:'12:40'},{r:'AXO-15',t:'bug',ti:'Таймер скидається у PiP',a:'me',sev:'Критичний'}],
  review:[{r:'AXO-16',t:'task',ti:'Self-host шрифтів: Literata, Manrope, Plex Mono',a:'ag',pr:true,comments:1}],
  done:[]
};
function card(it){
  const foot = [
    it.sev ? `<span class="chip danger">${it.sev}</span>` : '',
    it.blocked ? `<span class="chip warning">${ic('lock','sm')} ${it.blocked}</span>` : '',
    ...(it.tags||[]).map(x=>`<span class="chip">#${x}</span>`),
    it.pr ? `<span class="chip primary">${ic('pr','sm')} PR</span>` : '',
    it.comments ? `<span class="chip">${ic('msg','sm')} ${it.comments}</span>` : '',
    it.focus ? `<span class="chip accent">${ic('timer','sm')} ${it.focus}</span>` : ''
  ].join('');
  return `<article class="card ${it.lift?'lift':''}" style="--t:${T[it.t][0]}">
    <div class="meta">${glyph(it.t)}<span class="mono s muted" style="font-weight:500">${it.r}</span><span style="flex:1"></span>${av(it.a)}</div>
    <div class="title">${it.ti}</div>${foot?`<div class="foot">${foot}</div>`:''}
    ${it.act?`<div class="activity">${av('claude').replace('class="av','style="width:16px;height:16px;font-size:8px" class="av')}${it.act}</div>`:''}</article>`;
}
function rail(on){
  const items=[['tasks','Завдання'],['cal','Календар'],['timer','Помодоро'],['board','Проєкти']];
  return `<nav class="rail" aria-label="Навігація"><div style="margin-bottom:14px">${tileGills(40)}</div>${items.map(([k,l])=>`<a class="nav ${k===on?'on':''}">${ic(k,'lg')}${l}</a>`).join('')}<span class="sp"></span><a class="nav">${ic('bell','lg')}</a>${av('me').replace('class="av','style="width:36px;height:36px;font-size:13px" class="av')}</nav>`;
}
function tabbar(on){
  const items=[['tasks','Завдання'],['cal','Календар'],['timer','Помодоро'],['board','Проєкти']];
  return `<nav class="tabbar">${items.map(([k,l])=>`<a class="nav ${k===on?'on':''}">${ic(k,'lg')}${l}</a>`).join('')}</nav>`;
}
function ring(size, pct, color, digits, fs){
  const r = size/2 - 8, c = 2*Math.PI*r;
  return `<div class="ring" style="width:${size}px;height:${size}px"><svg width="${size}" height="${size}"><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="var(--surface-sunken)" stroke-width="${size>200?10:8}"/><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="${color}" stroke-width="${size>200?10:8}" stroke-linecap="round" stroke-dasharray="${c}" stroke-dashoffset="${c*(1-pct)}"/></svg><div style="text-align:center"><div class="digits" style="font-size:${fs}px;line-height:${fs*1.12}px">${digits}</div></div></div>`;
}

