    <main style="flex:1;padding:16px 20px;display:flex;flex-direction:column;gap:12px">${ITEMS.progress.map(card).join('')}${card({r:'AXO-26',t:'task',ti:'Перевірити контраст у темній темі',a:'ag',tags:['a11y']})}</main>
