function productShot(lang, m){
  const t = lang==='uk' ? {focus:'Фокус', done:'Сесію завершено — 25 хв. Перерва.', col:['В роботі','На рев’ю']} : {focus:'Focus', done:'Session done — 25 min. Take a break.', col:['In progress','In review']};
  const tr = it => lang==='uk' ? it : ({...it, ti:{'Токени кольору в index.css':'Colour tokens in index.css','Таймер скидається у PiP':'Timer resets in PiP','Self-host шрифтів: Literata, Manrope, Plex Mono':'Self-host fonts: Literata, Manrope, Plex Mono'}[it.ti]||it.ti, act: it.act ? 'Claude commented · 2 min ago':undefined, sev: it.sev ? 'Critical':undefined});
  return `<div style="position:relative;${m?'height:420px':'height:520px'}">
    <div style="position:absolute;inset:0 ${m?'0':'40px'} ${m?'60px':'40px'} 0;background:var(--surface);border:1px solid var(--border);border-radius:16px;box-shadow:var(--shadow-float);overflow:hidden">
      <div style="display:flex;gap:6px;padding:12px 14px;border-bottom:1px solid var(--border)"><span class="dot" style="--c:var(--border-strong)"></span><span class="dot" style="--c:var(--border-strong)"></span><span class="dot" style="--c:var(--border-strong)"></span><span class="mono s muted" style="margin-left:10px">axo · AXO</span></div>
      <div style="display:flex;gap:14px;padding:16px">${[[t.col[0],'progress',ITEMS.progress],[t.col[1],'review',ITEMS.review]].slice(0, m?1:2).map(([n,s,l])=>`<div class="col" style="width:${m?'100%':'250px'}"><div class="col-h"><span class="dot" style="--c:${STATUS[s][1]}"></span><span class="label">${n}</span></div>${l.map(x=>card(tr(x))).join('')}</div>`).join('')}</div>
    </div>
    <div style="position:absolute;right:0;bottom:${m?'0':'0'};width:${m?'190px':'230px'};background:var(--surface-raised);border:1px solid var(--border-strong);border-radius:16px;box-shadow:var(--shadow-pop);padding:16px;display:flex;flex-direction:column;align-items:center;gap:10px">
      <span class="chip accent">${t.focus}</span>${ring(m?110:130,0.49,'var(--phase-focus)','12:40',m?22:26)}<span class="mono s muted">AXO-17</span></div>
  </div>`;
}
