function renderMascot(el){
  const rules = [['success','Так','Порожні стани: один axl. на порожню колонку, порожня дошка чи беклог (нейтральний, грайливий)'],['success','Так','Момент «готово»: завершена сесія, усі задачі виконано (радість)'],['success','Так','Помилка, 404, офлайн (сум), з чіткою дією поруч'],['success','Так','Невеликий у hero лендінгу та у фінальному заклику, у кольорі primary'],['danger','Ні','Спінери, PiP-вікно, картки дошки, сповіщення'],['danger','Ні','Поверх скріншотів продукту; поруч із помилками втрати даних'],['danger','Ні','Повтор у кожному рядку: порожня історія на дошці — простий текст, без маскота'],['danger','Ні','Довгі репліки від імені axl. — максимум одне коротке речення']];
  el.innerHTML = `<div class="ab sheet"><div class="mascot-grid">${['neutral','joy','sad','playful'].map((e,i)=>`<div class="m-cell"><div class="m-stage">${axl(e,150)}</div><div class="m-stage dk"><div style="width:150px;color:#A9D6B9">${axlSvg(e)}</div></div><span class="s strong">${['нейтральний — порожні стани','радість — «готово»','сум — помилка, офлайн','грайливий — фінальний CTA'][i]}</span></div>`).join('')}</div>
    <div class="rules">${rules.map(([c,h,t])=>`<div class="rule"><span class="chip ${c}">${h}</span><span>${t}</span></div>`).join('')}</div></div>`;
}
function renderDoDont(el){
  const L=[['Так','success',['Помаранчевий (accent) — лише фаза фокусу й точкові акценти','Literata — від 20 px: лендінг, h1, назва задачі в панелі','Рефи й таймер — IBM Plex Mono з табличними цифрами','Статус = колір + форма (кільце, перекреслення); тип = колір + іконка (crown, book, check, bug)','Видимий focus-ring 2 px (--color-ring) на кожному інтерактивному елементі','Тексти: коротко, по-майстерськи; «агенти» — як факт, не обіцянка']],
           ['Ні','danger',['Не фарбувати типи задач у primary чи accent','Без serif у картках, чипах, таблицях, markdown і PiP','Без «AI», «smart», «copilot», «для команд» у текстах','Не використовувати сірий тексту з контрастом < 4.5:1','Не плодити радіуси: лише 6 / 10 / 16 / full','Не копіювати логотипи й кольори інших трекерів (ADO, Jira)']]];
  el.innerHTML = `<div class="dd">${L.map(([h,c,items])=>`<div class="ab sheet"><div class="hrow" style="align-items:center">${c==='success'?roundCheck('var(--success)',22):`<svg width="22" height="22" viewBox="0 0 20 20" aria-hidden="true"><circle cx="10" cy="10" r="8.5" fill="var(--danger)"/><path d="M7 7l6 6M13 7l-6 6" stroke="var(--surface-raised)" stroke-width="1.9" stroke-linecap="round"/></svg>`}<span class="serif" style="font-size:20px;color:var(--${c})">${h}</span></div><ul style="margin:12px 0 0;padding-left:18px;line-height:24px">${items.map(i=>`<li>${i}</li>`).join('')}</ul></div>`).join('')}</div>`;
}

/* ---------- fit artboards ---------- */
function AxoFit(){
  const fit = () => document.querySelectorAll('.ab-wrap').forEach(w=>{
    const ab=w.firstElementChild, W=+ab.dataset.w; ab.style.width=W+'px';
    const s=Math.min(1, w.clientWidth / W); ab.style.transform=`scale(${s})`; w.style.height=(ab.offsetHeight*s)+'px'; });
  fit();
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);
  try { new ResizeObserver(fit).observe(document.querySelector('.page')); } catch(e){ window.addEventListener('resize', fit); }
}
